    "ix.0": "گریڈ 5 · امریکی تاریخ · §113.16 · مسئلہ پر مبنی تعلیم",
    "ix.1": "ایک نئی زندگی — ہجرت کا سوال، 1914",
    "ix.2": "ایک مسئلہ پر مبنی تعلیمی یونٹ۔ طلبہ 1914 کے نیویارک بندرگاہ میں قدم رکھتے ہیں، کسی فریق کا نقطۂ نظر اپناتے ہیں، اور ایک حقیقی، غیر واضح ساخت والے سوال پر کام کرتے ہیں — سطحی سے گہری اور پھر منتقلی تک سیکھنے کی تعمیر کرتے ہوئے۔ اُستاد رہنما ہے، جوابی کلید نہیں۔",
    "ix.3": "<b>محرک سوال:</b> سال 1914 ہے۔ کیا بالڈونی خاندان کو یہاں ایک نئی زندگی بنانے کی اجازت ہونی چاہیے — اور کیسے؟ اُن کی جگہ، اور فیصلہ کرنے والوں کی جگہ ہوتے تو <i>تم</i> کیا کرتے؟",
    "ix.4": "تین مرحلوں کا راستہ (اِنہیں ترتیب سے کریں)",
    "ix.5": "مسئلہ حل کرنا ایک <b>منتقلی</b> اقدام ہے — یہ تبھی کام کرتا ہے جب طلبہ کے پاس استدلال کے لیے علم ہو۔ اِسی لیے مرحلہ 3 کا مسئلہ جان بوجھ کر مرحلہ 1 اور 2 کے پیچھے <b>مقفل</b> رکھا گیا ہے۔",
    "ix.6": "علم کی تعمیر کریں",
    "ix.7": "الفاظ، 1900 کی دہائی کی ہجرت کے کلیدی حقائق، ایک جِگسا مطالعہ، اور نقشے کا کام۔ ~1–2 پیریڈ۔",
    "ix.8": "جوڑیں اور ترتیب دیں",
    "ix.9": "دھکیلنے–کھینچنے کے عوامل کا تصوراتی نقشہ، بنیادی مآخذ، نقطہ ہائے نظر، اور ایک منظم دلیل۔ ~1–2 پیریڈ۔",
    "ix.10": "مسئلہ حل کریں",
    "ix.11": "مسئلے سے ملیں، ایک کردار لیں، تحقیق کریں، حل تجویز کریں اور اُس کا دفاع کریں، اور جائزہ لیں۔ ~2–4 پیریڈ۔",
    "ix.12": "⛔ <b>قفل:</b> جب تک طلبہ سطحی اور گہری سرگرمیاں مکمل نہ کر لیں، مرحلہ 3 کا مسئلہ نہ کھولیں۔ مسئلے سے بہت جلد ملنا تحقیق کو اندازے میں بدل دیتا ہے۔",
    "ix.13": "بڑا خیال اور اہداف",
    "ix.14": "<b>بڑا خیال:</b> لوگ یہ فیصلہ کرتے وقت کہ آیا اور کیسے نئی زندگی بنائیں، <b>دھکیلنے اور کھینچنے والے عوامل</b> اور حقیقی حدود کو تولتے ہیں — اور اُن لاکھوں فیصلوں نے امریکہ کی ہجرت، صنعت کاری اور شہروں کو تشکیل دیا۔",
    "ix.15": "<b>جانیں:</b> لوگ 1900 کے آس پاس کیوں ہجرت کرتے تھے، ایلس آئی لینڈ پر پہنچنے میں کیا شامل تھا، اور ہجرت نے صنعتی شہروں کو کیسے پروان چڑھایا۔",
    "ix.16": "<b>سمجھیں:</b> وہی واقعہ ہر فریق کے نقطۂ نظر سے مختلف نظر آتا ہے۔",
    "ix.17": "<b>کریں:</b> مسئلہ حل کرنے کے عمل کو شروع سے آخر تک چلائیں — مسئلہ متعین کریں، معلومات جمع کریں، اختیارات تولیں، حل چنیں اور اُس کا دفاع کریں، اور اُس کا جائزہ لیں (§113.16(c)(26)(B))۔",
    "ix.18": "وہ معیارات جن سے یہ یونٹ ہم آہنگ ہے (§113.16)",
